type BadgeVariant = 'success' | 'warning' | 'danger' | 'info';

@Component({
  selector: 'app-badge',
  templateUrl: './badge.component.html',
  styleUrl: './badge.component.css',
})
export class BadgeComponent {
  @Input() variant: BadgeVariant = 'info';
}

import { Component, Input } from '@angular/core';

type ButtonVariant = 'primary' | 'secondary' | 'danger' | 'ghost';
type ButtonType = 'button' | 'submit' | 'reset';

@Component({
  selector: 'app-button',
  templateUrl: './button.component.html',
  styleUrl: './button.component.css',
})
export class ButtonComponent {
  @Input() variant: ButtonVariant = 'primary';
  @Input() type: ButtonType = 'button';
  @Input() icon = false;
  @Input() disabled = false;
  @Input() hover = false;
  @Input() ariaLabel = '';
}

import { Component, Input } from '@angular/core';

interface CalendarDay {
  label: string;
  muted?: boolean;
}

@Component({
  selector: 'app-calendar',
  templateUrl: './calendar.component.html',
  styleUrl: './calendar.component.css',
})
export class CalendarComponent {
  @Input() title = 'Junho 2026';
  @Input() today = 12;
  @Input() selected = 12;
  @Input() events: number[] = [];

  readonly weekdays = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sab'];
  readonly days: CalendarDay[] = [
    { label: '31', muted: true },
    ...Array.from({ length: 30 }, (_, index) => ({ label: String(index + 1) })),
    { label: '1', muted: true },
    { label: '2', muted: true },
    { label: '3', muted: true },
    { label: '4', muted: true },
  ];

  select(day: CalendarDay): void {
    if (!day.muted) {
      this.selected = Number(day.label);
    }
  }

  hasEvent(day: CalendarDay): boolean {
    return !day.muted && this.events.includes(Number(day.label));
  }
}

